export function getLang() {
  const l = document.documentElement.getAttribute('lang');
  if (l === 'en' || l === 'es') { return l; }
  try { const s = localStorage.getItem('lf-site-lang'); if (s === 'en' || s === 'es') { return s; } } catch (e) { /* ignore */ }
  return 'es';
}

export const missingKeys = new Set();

export function t(key, params) {
  const lang = getLang();
  let s = DICT[lang][key];
  if (s == null) { s = DICT.es[key]; }
  if (s == null) { missingKeys.add(key); return key; }
  if (params) {
    s = s.replace(/\{(\w+)\}/g, (m, k) => {
      if (params[k] == null) { return m; }
      if (k === 'skill' && DICT[lang][`skill.${params[k]}`]) { return DICT[lang][`skill.${params[k]}`]; }
      return String(params[k]);
    });
  }
  return s;
}

export function onLangChange(fn) {
  let current = getLang();
  const obs = new MutationObserver(() => {
    const now = getLang();
    if (now !== current) { current = now; fn(now); }
  });
  obs.observe(document.documentElement, { attributes: true, attributeFilter: ['lang'] });
}

export const _DICT = DICT;
